}

std::vector<Triangulation::Vertex_handle> vertices;
vertices.reserve(polygon_coords.size());

for (size_t i = 0; i < polygon_coords.size(); ++i) {
    const std::vector<double>& coord = polygon_coords[i];
    if (coord.size() < 3) continue;

    Kernel::Point_3 p3(coord[0], coord[1], coord[2]);
    // Project the 3D point onto the 2D plane for the triangulation
    Kernel::Point_2 p2 = plane.project(p3);

    // Insert point into triangulation using the walk_start hint
    Triangulation::Vertex_handle vh = triangulation.insert(p2, walk_start);

    // Store the original 3D point in the vertex info
    vh->info().point = p3;
    vh->info().has_point = true;

    vertices.push_back(vh);

    // Update walk_start to the last inserted vertex's incident face to speed up next insertion
    if (triangulation.is_infinite(vh)) {
        // Handle infinite vertex case if necessary, though unlikely for polygon coords
    } else {
        // Use any face incident to the new vertex as the next walk start
        // In CGAL CDT, we can find a face by looking at the vertex's incident faces
        // For simplicity, we can use the triangulation's internal mechanisms or just keep the current walk_start
    }
}

// Insert constraints between consecutive vertices to form the polygon boundary
for (size_t i = 0; i < vertices.size(); ++i) {
    Triangulation::Vertex_handle v_start = vertices[i];
    Triangulation::Vertex_handle v_end = vertices[(i + 1) % vertices.size()];

    if (v_start != v_end) {
        // Use the enhanced triangulation's method to insert constraints
        // This handles intersections and ensures the constraint is present
        triangulation.odd_even_insert_constraint(v_start, v_end);
    }
}

